function bellmanFord(nodeCount, edges, source) {
  const dist = new Array(nodeCount).fill(Infinity);
  dist[source] = 0;

  // V-1 rounds: a shortest path uses at most V-1 edges.
  for (let round = 0; round < nodeCount - 1; round++) {
    let changed = false;
    for (const { from, to, weight } of edges) {
      if (dist[from] === Infinity) continue;
      if (dist[from] + weight < dist[to]) {
        dist[to] = dist[from] + weight;
        changed = true;
      }
    }
    if (!changed) break;              // settled early, common in practice
  }

  // One more round. Any improvement now means a negative cycle.
  for (const { from, to, weight } of edges) {
    if (dist[from] !== Infinity && dist[from] + weight < dist[to]) {
      return { dist: null, negativeCycle: true };
    }
  }

  return { dist, negativeCycle: false };
}

