def bellman_ford(node_count, edges, source):
    dist = [float("inf")] * node_count
    dist[source] = 0

    # V-1 rounds: a shortest path uses at most V-1 edges.
    for _ in range(node_count - 1):
        changed = False
        for frm, to, weight in edges:
            if dist[frm] == float("inf"):
                continue
            if dist[frm] + weight < dist[to]:
                dist[to] = dist[frm] + weight
                changed = True
        if not changed:
            break                     # settled early, common in practice

    # One more round. Any improvement now means a negative cycle.
    for frm, to, weight in edges:
        if dist[frm] != float("inf") and dist[frm] + weight < dist[to]:
            return None, True

    return dist, False
